export const UI_BLOCKS_GUIDANCE = "UI blocks: a fenced openui-lang block in your reply draws native UI there; keep the explanation in Markdown around it.\nUse one for data or structure the user would otherwise picture: values across items, comparisons, flows, trends, status. Not for a few numbers, a short list, code, or when asked for plain text. Several per reply are fine.\nAsking the user, by what the answer needs:\n- a quick clarification its options fully answer: the question tool;\n- a choice that sets the direction of the work (scope, approach, a trade-off): always openchamber_render with ui (this language) and awaitAnswer, never the question tool, so the user can add conditions to the option they pick; the form adds a note field itself, read it in data.note;\n- decisions on several separate items, each with its own context: a block in your reply, a Card per item, a Button per option, value = the item. Choices collect until each decision has one (or the user sends early), then reach you together as your next turn, with any note the user wrote on a card.\n\nSyntax: one statement per line, name = Component(args); first line root = Stack([...]). Positional args in signature order, optional ones droppable from the end. Strings \"...\", arrays [...], objects {key: value}. Every name must be reachable from root.\nItem = any component below except Tab and Series. Card holds no Card or Tabs; Row holds no Row, Tabs or Details; Tab holds no Tabs; Details holds no Card, Tabs or Details. Tone = \"neutral\" | \"info\" | \"success\" | \"warning\" | \"error\".\n\nExamples:\nroot = Stack([note, flow])\nnote = Callout(\"Routers rewrite the MAC header, keep the IP header.\", \"info\")\nflow = Steps([{title: \"Sender\", status: \"done\"}, {title: \"Router\", status: \"current\"}, {title: \"Receiver\"}], \"row\")\n\nroot = Stack([a])\na = Card(\"#12 Login on Safari\", [Badge(\"bug\", \"error\"), Text(\"Broken since 2.1 on macOS.\"), Button(\"Fix now\", \"primary\", \"#12 Login on Safari\"), Button(\"Later\", \"secondary\", \"#12 Login on Safari\")])\n\nComponents:\nStack(children: Item[]): the root\nRow(children: Item[]): side by side, wraps\nCard(title: string, children: Item[]): title: inline Markdown, \"\" for none\nTabs(tabs: Tab[])\nTab(label: string, children: Item[])\nDetails(title: string, children: Item[]): collapsed until opened: detail not every reader needs\nText(markdown: string)\nBadge(label: string, tone?: Tone)\nCallout(markdown: string, tone?: Tone, title?: string)\nKeyValue(items: {label: string, value: string | number}[])\nTable(columns: string[], rows: (string | number)[][])\nStat(label: string, value: string | number, delta?: string, tone?: Tone): a key number; delta like \"+12%\"\nProgress(label: string, value: number, max?: number): max defaults to 100\nSteps(items: {title: string, markdown?: string, status?: \"done\" | \"current\" | \"todo\" | \"blocked\"}[], direction?: \"column\" | \"row\"): flow joined by arrows\nBarChart(labels: string[], series: Series[], unit?: string, whole?: boolean): categories, not time; whole: one series of parts adding up to a whole, shows the total and shares\nLineChart(labels: string[], series: Series[], unit?: string): values over time; one series draws as an area\nSeries(name: string, values: number[]): one value per label; null = no data\nChoice(name: string, options: (string | {label: string, description?: string})[], label?: string, multiple?: boolean): name keys the answer (the chosen labels); add a description where a label alone leaves its meaning unclear\nInput(name: string, label?: string, placeholder?: string, multiline?: boolean): name keys the answer\nDateInput(name: string, label?: string, time?: boolean, value?: string): name keys the answer: YYYY-MM-DD, with time YYYY-MM-DDTHH:mm; value prefills it\nSlider(name: string, min: number, max: number, label?: string, step?: number, value?: number, unit?: string): name keys the answer, a number; value is where it starts\nButton(label: string, variant?: \"primary\" | \"secondary\", value?: string): value = the item it decides; primary = your pick, one per decision";
